import { useTranslation } from 'react-i18next'
import { Badge } from '@/components/ui/badge'
import { AbsenceRequestStatusBadge } from '@/features/absences/requests/absence-request-status-badge'
import type { AbsenceRequest } from '@/features/absences/types'

/** Status plus the two server-fixed flags of a request: out of notice and generated by a collective leave. */
export function AbsenceRequestFlagBadges({ request }: { request: AbsenceRequest }) {
  const { t } = useTranslation()

  return (
    <>
      <AbsenceRequestStatusBadge status={request.status} />
      {request.is_short_notice ? <Badge variant="outline">{t('absences.badges.shortNotice')}</Badge> : null}
      {request.company_closure ? (
        <Badge
          variant="outline"
          title={t('absences.requests.detail.collectiveLeaveTitle', { name: request.company_closure.name })}
        >
          {t('absences.badges.collectiveLeave')}
        </Badge>
      ) : null}
    </>
  )
}
